Code.Terraform:
```hcl
# SageMaker AI endpoint configuration with inference data capture enabled
resource "aws_sagemaker_endpoint_configuration" "<example_resource_name>" {
  name = "<example_resource_name>"

  production_variants {
    variant_name           = "AllTraffic"
    model_name             = "<example_model_name>"
    initial_instance_count = 1
    instance_type          = "ml.m5.large"
  }

  data_capture_config {
    enable_capture              = true # CRITICAL: turns inference data capture on
    initial_sampling_percentage = 100
    destination_s3_uri          = "s3://<example_bucket>/datacapture/"
    kms_key_id                  = "<example_kms_key_arn>"

    capture_options {
      capture_mode = "InputAndOutput"
    }
  }
}
```
